import re

KEY = re.compile(r"(?<![A-Za-z0-9])([A-Z]{2,})-([1-9][0-9]*)(?![A-Za-z0-9])")

def extract_keys(texts, spaces):
    allowed = set(spaces)
    out = []
    for t in texts:
        seen, keys = set(), []
        for m in KEY.finditer(t):
            key = m.group(0)
            if allowed and m.group(1) not in allowed:
                continue
            if key not in seen:
                seen.add(key)
                keys.append(key)
        out.append(keys)
    return out

jira-workflow-transitions.solution:
def simulate(workflow, category, start, created, events, end):
    status, since = start, created
    rejected, reopens, spent = [], 0, {}
    for i, (day, name) in enumerate(events):
        target = workflow.get(status, {}).get(name)
        if target is None:
            rejected.append(i)
            continue
        cat = category[status]
        spent[cat] = spent.get(cat, 0) + (day - since)
        if cat == "Done" and category[target] != "Done":
            reopens += 1
        status, since = target, day
    cat = category[status]
    spent[cat] = spent.get(cat, 0) + (end - since)
    return {"final": status, "rejected": rejected, "reopens": reopens, "in_progress_days": spent.get("In Progress", 0)}

