import re

KEYWORDS = {"AND", "OR", "NOT", "IN", "IS", "EMPTY", "NULL", "ORDER", "BY", "ASC", "DESC"}
WORD_CHARS = set("ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789_.-+")

def tokenize(q):
    toks, i, n = [], 0, len(q)
    while i < n:
        c = q[i]
        if c in " \t\n\r":
            i += 1
        elif c in "\"'":
            j, buf = i + 1, []
            while j < n and q[j] != c:
                if q[j] == "\\" and j + 1 < n:
                    j += 1
                buf.append(q[j])
                j += 1
            if j >= n:
                return [["ERROR", i]]
            toks.append(["STRING", "".join(buf)])
            i = j + 1
        elif c == "(":
            toks.append(["LPAREN", "("])
            i += 1
        elif c == ")":
            toks.append(["RPAREN", ")"])
            i += 1
        elif c == ",":
            toks.append(["COMMA", ","])
            i += 1
        elif q[i:i + 2] in ("!=", ">=", "<=", "!~"):
            toks.append(["OP", q[i:i + 2]])
            i += 2
        elif c in "=<>~":
            toks.append(["OP", c])
            i += 1
        elif c in WORD_CHARS:
            j = i
            while j < n and q[j] in WORD_CHARS:
                j += 1
            w = q[i:j]
            if w.upper() in KEYWORDS:
                toks.append(["KEYWORD", w.upper()])
            else:
                toks.append(["WORD", w])
            i = j
        else:
            return [["ERROR", i]]
    return toks

