        return []
    return list(v) if isinstance(v, list) else [v]

def _num(x):
    return isinstance(x, (int, float)) and not isinstance(x, bool)

def _eq(x, s):
    if _num(x):
        try:
            return float(s) == float(x)
        except ValueError:
            return False
    return str(x).lower() == s.lower()

def _order_cmp(x, s):
    if _num(x):
        try:
            y = float(s)
        except ValueError:
            return None
